body { margin: 8px; }
iframe { border: 2px solid #555; display: block; margin-top: 8px; }
#same { width: 460px; height: 150px; }
#cross { width: 460px; height: 110px; }

(() => {
  // Seeds are concatenated so the script's own text never contains one.
  const seed = (name, number) => 'SEED-TRK-' + name + '-' + number;
  const open = document.querySelector('#open-host').attachShadow({ mode: 'open' });
  open.innerHTML =
    '<input id="open-revealed" type="password">' +
    '<input id="open-plain" value="open plain value">' +
    '<label id="open-remember-label">Remember me <input id="open-remember" type="checkbox"></label>' +
    '<label id="open-mirror-label">Saved: <b id="open-mirror-text"></b> <input id="open-mirror" type="password"></label>' +
    '<label id="open-password-label">Password <input id="open-password" type="password"></label>' +
    '<textarea id="open-note">open note</textarea>' +
    '<textarea id="open-secret-note" autocomplete="one-time-code"></textarea>' +
    '<input id="move-stl" type="password"><input id="move-rtr" type="password">';
  const revealed = open.querySelector('#open-revealed');
  revealed.value = seed('OPEN', 1101);
  revealed.type = 'text';
  const mirror = open.querySelector('#open-mirror');
  mirror.value = seed('MIRROR', 1102);
  mirror.type = 'text';
  open.querySelector('#open-mirror-text').textContent = mirror.value;
  open.querySelector('#open-secret-note').value = seed('OTP', 1107);
  const closed = document.querySelector('#closed-host').attachShadow({ mode: 'closed' });
  closed.innerHTML =
    '<input id="closed-revealed" type="password">' +
    '<input id="closed-plain" value="closed plain value">';
  const closedRevealed = closed.querySelector('#closed-revealed');
  closedRevealed.value = seed('CLOSED', 1103);
  closedRevealed.type = 'text';
  // History belongs to the element (D5): each is revealed in one scope
  // and moved to another before the first model observation.
  const lts = document.querySelector('#move-lts');
  lts.value = seed('LTS', 1110);
  lts.type = 'text';
  open.append(lts);
  const stl = open.querySelector('#move-stl');
  stl.value = seed('STL', 1111);
  stl.type = 'text';
  document.querySelector('#light-dock').append(stl);
  const rtr = open.querySelector('#move-rtr');
  rtr.value = seed('RTR', 1112);
  rtr.type = 'text';
  closed.append(rtr);
})();

